public List<List<Integer>> kSmallestPairs(int[] nums1, int[] nums2, int k) {
    List<int[]> all = new ArrayList<>();
    for (int x : nums1) {
        for (int y : nums2) {
            all.add(new int[]{x, y});
        }
    }
    all.sort((a, b) -> Integer.compare(a[0] + a[1], b[0] + b[1]));
    List<List<Integer>> result = new ArrayList<>();
    for (int i = 0; i < Math.min(k, all.size()); i++) {
        result.add(Arrays.asList(all.get(i)[0], all.get(i)[1]));
    }
    return result;
}

public List<List<Integer>> kSmallestPairs(int[] nums1, int[] nums2, int k) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums1.length == 0 || nums2.length == 0 || k == 0) {
        return result;
    }
    // heap holds {i, j}; ordered by nums1[i] + nums2[j]
    PriorityQueue<int[]> minHeap = new PriorityQueue<>(
        (a, b) -> Integer.compare(nums1[a[0]] + nums2[a[1]], nums1[b[0]] + nums2[b[1]]));
    for (int i = 0; i < Math.min(nums1.length, k); i++) {
        minHeap.offer(new int[]{i, 0});
    }
    while (k > 0 && !minHeap.isEmpty()) {
        int[] top = minHeap.poll();
        int i = top[0], j = top[1];
        result.add(Arrays.asList(nums1[i], nums2[j]));
        k--;
        if (j + 1 < nums2.length) {
            minHeap.offer(new int[]{i, j + 1});
        }
    }
    return result;
}

